/**
 * Formatadores das telas de Operações.
 *
 * `BRL` reaproveita `formatCurrency` e as datas usam `dateFormater`, ambos de
 * `@/functions/formaters`. Os demais ficam aqui porque o equivalente do repo
 * entrega outro formato: `formatCompactCurrency` usa sufixo `M`/`k` em vez do
 * `mi`/`mil` pt-BR, e `formatNumberToPercentage` tem
 * `maximumSignificantDigits: 4`, que anula o `minimumFractionDigits: 2` e faz
 * "12,50%" sair como "12,5%" — o que quebra o alinhamento das colunas
 * `tabular-nums` destas telas.
 */

import { formatCurrency } from '@/functions/formaters/formatCurrency';

/** R$ 1.234,56 */
export const BRL = (n: number): string => formatCurrency(n);

/** R$ 1.235 — sem centavos, para tabelas densas. */
export const BRLc = (n: number): string =>
    'R$ ' + n.toLocaleString('pt-BR', { maximumFractionDigits: 0 });

